package audio

import (
	"bytes"
	"os"
	"path/filepath"
	"slices"
	"testing"
)

// The fixtures under testdata are generated by ffmpeg and the reference FLAC
// tools; the expected values below come from metaflac, not from this package.
const (
	fixtureSine16   = "sine16.flac"
	fixtureHires24  = "hires24.flac"
	fixturePadded24 = "padded24.flac"
	fixtureSilence  = "silence.flac"
	fixtureID3      = "id3prefixed.flac"
)

func fixture(t *testing.T, name string) string {
	t.Helper()
	return filepath.Join("testdata", name)
}

func TestProbeStreamInfo(t *testing.T) {
	tests := []struct {
		file          string
		sampleRate    int
		channels      int
		bitsPerSample int
		totalSamples  uint64
		md5           string
	}{
		{fixtureSine16, 44100, 2, 16, 8820, "5b12f525bf63067030d6ee676a335991"},
		{fixtureHires24, 96000, 2, 24, 9600, "a060ff1bbd5a846ef54ed3d4f37f8be9"},
		{fixturePadded24, 44100, 2, 24, 8820, "01dc911a7a139a61bd0c5ad7ff0c6b9d"},
		{fixtureSilence, 44100, 2, 16, 4410, "882c7029a5097769b85bd176f5752684"},
	}
	for _, tt := range tests {
		t.Run(tt.file, func(t *testing.T) {
			m, err := Probe(fixture(t, tt.file))
			if err != nil {
				t.Fatalf("Probe() error = %v", err)
			}

			got := m.StreamInfo
			if got.SampleRate != tt.sampleRate {
				t.Errorf("SampleRate = %d, want %d", got.SampleRate, tt.sampleRate)
			}
			if got.Channels != tt.channels {
				t.Errorf("Channels = %d, want %d", got.Channels, tt.channels)
			}
			if got.BitsPerSample != tt.bitsPerSample {
				t.Errorf("BitsPerSample = %d, want %d", got.BitsPerSample, tt.bitsPerSample)
			}
			if got.TotalSamples != tt.totalSamples {
				t.Errorf("TotalSamples = %d, want %d", got.TotalSamples, tt.totalSamples)
			}
			if !got.MD5Present {
				t.Error("MD5Present = false, want true")
			}
			if got.MD5 != tt.md5 {
				t.Errorf("MD5 = %q, want %q", got.MD5, tt.md5)
			}
		})
	}
}

func TestProbeFormatConversion(t *testing.T) {
	m, err := Probe(fixture(t, fixtureHires24))
	if err != nil {
		t.Fatalf("Probe() error = %v", err)
	}

	format := m.StreamInfo.Format()
	if err := format.Validate(); err != nil {
		t.Errorf("Format().Validate() error = %v", err)
	}
	if format.SampleRate != 96000 || format.Channels != 2 || format.BitsPerSample != 24 {
		t.Errorf("Format() = %+v, want 96000/2/24", format)
	}
}

func TestStreamInfoDuration(t *testing.T) {
	tests := []struct {
		name string
		info StreamInfo
		want float64
	}{
		{"one second", StreamInfo{SampleRate: 44100, TotalSamples: 44100}, 1},
		{"half a second", StreamInfo{SampleRate: 96000, TotalSamples: 48000}, 0.5},
		{"unknown length", StreamInfo{SampleRate: 44100}, 0},
		{"unknown rate", StreamInfo{TotalSamples: 44100}, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.info.Duration(); got != tt.want {
				t.Errorf("Duration() = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestProbeVorbisComment(t *testing.T) {
	m, err := Probe(fixture(t, fixtureSine16))
	if err != nil {
		t.Fatalf("Probe() error = %v", err)
	}

	if !m.HasVorbisComment {
		t.Fatal("HasVorbisComment = false, want true")
	}
	if m.Vendor == "" {
		t.Error("Vendor is empty, want the encoder string")
	}
}

func TestProbeFileSizeAndOffset(t *testing.T) {
	path := fixture(t, fixtureSine16)
	info, err := os.Stat(path)
	if err != nil {
		t.Fatalf("Stat() error = %v", err)
	}

	m, err := Probe(path)
	if err != nil {
		t.Fatalf("Probe() error = %v", err)
	}
	if m.FileSize != info.Size() {
		t.Errorf("FileSize = %d, want %d", m.FileSize, info.Size())
	}
	if m.AudioOffset != 0 {
		t.Errorf("AudioOffset = %d, want 0 for a well-formed file", m.AudioOffset)
	}
	if len(m.ForeignTags) != 0 {
		t.Errorf("ForeignTags = %v, want none", m.ForeignTags)
	}
}

// TestProbeSkipsLeadingID3 covers a file that is malformed but common: an
// ID3v2 block prepended to a FLAC stream, which the decoder cannot read past
// on its own.
func TestProbeSkipsLeadingID3(t *testing.T) {
	m, err := Probe(fixture(t, fixtureID3))
	if err != nil {
		t.Fatalf("Probe() error = %v", err)
	}

	if m.AudioOffset != 20 {
		t.Errorf("AudioOffset = %d, want 20", m.AudioOffset)
	}
	if !slices.Contains(m.ForeignTags, TagID3v2) {
		t.Errorf("ForeignTags = %v, want it to contain %q", m.ForeignTags, TagID3v2)
	}
	if m.StreamInfo.SampleRate != 44100 {
		t.Errorf("SampleRate = %d, want 44100", m.StreamInfo.SampleRate)
	}
}

func TestProbeMissingFile(t *testing.T) {
	if _, err := Probe(filepath.Join("testdata", "does-not-exist.flac")); err == nil {
		t.Fatal("Probe() on a missing file succeeded, want error")
	}
}

func TestProbeNonFLAC(t *testing.T) {
	path := filepath.Join(t.TempDir(), "not-audio.flac")
	if err := os.WriteFile(path, []byte("this is not a FLAC stream at all"), 0o600); err != nil {
		t.Fatalf("WriteFile() error = %v", err)
	}
	if _, err := Probe(path); err == nil {
		t.Fatal("Probe() on a non-FLAC file succeeded, want error")
	}
}

func TestLeadingTagLength(t *testing.T) {
	tests := []struct {
		name       string
		data       []byte
		wantOffset int64
		wantTag    bool
		wantErr    bool
	}{
		{
			name:       "no tag",
			data:       []byte("fLaC and then some payload bytes"),
			wantOffset: 0,
		},
		{
			name:       "short file",
			data:       []byte("fLaC"),
			wantOffset: 0,
		},
		{
			name:       "empty file",
			data:       nil,
			wantOffset: 0,
		},
		{
			name:       "tag without footer",
			data:       append([]byte{'I', 'D', '3', 4, 0, 0, 0, 0, 0, 10}, make([]byte, 10)...),
			wantOffset: 20,
			wantTag:    true,
		},
		{
			name:       "tag with footer",
			data:       append([]byte{'I', 'D', '3', 4, 0, 0x10, 0, 0, 0, 10}, make([]byte, 20)...),
			wantOffset: 30,
			wantTag:    true,
		},
		{
			name:       "multi byte syncsafe size",
			data:       append([]byte{'I', 'D', '3', 4, 0, 0, 0, 0, 1, 0}, make([]byte, 128)...),
			wantOffset: 138,
			wantTag:    true,
		},
		{
			name:    "size byte with its high bit set is malformed",
			data:    []byte{'I', 'D', '3', 4, 0, 0, 0, 0, 0, 0x80},
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			offset, names, err := leadingTagLength(bytes.NewReader(tt.data))
			if (err != nil) != tt.wantErr {
				t.Fatalf("leadingTagLength() error = %v, wantErr %v", err, tt.wantErr)
			}
			if tt.wantErr {
				return
			}
			if offset != tt.wantOffset {
				t.Errorf("offset = %d, want %d", offset, tt.wantOffset)
			}
			if got := slices.Contains(names, TagID3v2); got != tt.wantTag {
				t.Errorf("ForeignTags = %v, want ID3v2 present = %v", names, tt.wantTag)
			}
		})
	}
}

func TestTrailingTagNames(t *testing.T) {
	pad := func(n int) []byte { return bytes.Repeat([]byte{'x'}, n) }

	tests := []struct {
		name string
		data []byte
		want []string
	}{
		{
			name: "no trailing tags",
			data: pad(400),
			want: nil,
		},
		{
			name: "id3v1 only",
			data: append(pad(400), append([]byte("TAG"), pad(125)...)...),
			want: []string{TagID3v1},
		},
		{
			name: "ape only",
			data: append(pad(400), append([]byte("APETAGEX"), pad(24)...)...),
			want: []string{TagAPEv2},
		},
		{
			name: "ape before id3v1",
			data: func() []byte {
				out := pad(400)
				out = append(out, append([]byte("APETAGEX"), pad(24)...)...)
				out = append(out, append([]byte("TAG"), pad(125)...)...)
				return out
			}(),
			want: []string{TagID3v1, TagAPEv2},
		},
		{
			name: "file shorter than a tag",
			data: pad(4),
			want: nil,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := trailingTagNames(bytes.NewReader(tt.data), int64(len(tt.data)))
			if err != nil {
				t.Fatalf("trailingTagNames() error = %v", err)
			}
			if !slices.Equal(got, tt.want) {
				t.Errorf("trailingTagNames() = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestHasMarkerAtRejectsNegativeOffset(t *testing.T) {
	got, err := hasMarkerAt(bytes.NewReader([]byte("abc")), -10, []byte("abc"))
	if err != nil {
		t.Fatalf("hasMarkerAt() error = %v", err)
	}
	if got {
		t.Error("hasMarkerAt() = true for a negative offset, want false")
	}
}
